INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''zipper'' primarily classified by, in terms of its teeth/coil material?', '["Metal, plastic (molded), or nylon coil — each with different strength, flexibility, and appearance characteristics","Only by its color, with no distinction in material or mechanism","Only by length, with all zippers using identical tooth material","Zippers have no meaningful classification system at all"]'::jsonb, 'Metal, plastic (molded), or nylon coil — each with different strength, flexibility, and appearance characteristics', 'Zippers are commonly classified by tooth/coil type — metal (durable, often decorative, used in jeans), molded plastic (chunky, often used in outerwear), or nylon coil (flexible, lightweight, common in everyday garments) — each suited to different garment types and aesthetics.', 1, '{"zipper-types"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is a ''invisible zipper'' (concealed zipper) designed to do differently from a standard exposed zipper?', '["Hide the zipper teeth/tape completely within the seam so only a thin seam line is visible from the garment''s right side","Make the zipper completely non-functional, purely decorative","Replace the need for any zipper pull tab","Increase the visibility of the zipper as a design feature"]'::jsonb, 'Hide the zipper teeth/tape completely within the seam so only a thin seam line is visible from the garment''s right side', 'An invisible zipper is constructed and sewn so its coil/teeth curl inward and sit hidden within the seam allowance, making it appear from the outside as a plain seam with no visible zipper — commonly used on dresses and skirts for a clean aesthetic.', 1, '{"invisible-zipper"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'What is the purpose of a ''label'' (main label/brand label) sewn into a garment, beyond simple branding?', '["It typically also identifies the brand, and combined with the care label, provides required information like fiber content and country of origin","Labels serve no informational purpose whatsoever, purely decorative","Labels are required only for luxury garments, never for standard apparel","A garment''s main label always replaces the need for any separate care label"]'::jsonb, 'It typically also identifies the brand, and combined with the care label, provides required information like fiber content and country of origin', 'While the main/brand label primarily identifies the brand, garment labeling overall (often combined with size and care labels) also fulfills legal requirements in many markets — like disclosing fiber content and country of origin — not just serving a branding purpose.', 1, '{"garment-labeling"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'Why is a garment''s ''country of origin'' label a legal requirement in many import markets (like the US or EU)?', '["It allows customs authorities and consumers to verify where a garment was manufactured, supporting trade regulation, tariff classification, and consumer information rights","Country of origin labeling exists purely as a marketing gimmick with no regulatory basis","This requirement only applies to raw fabric, never to finished garments","Country of origin has no relationship to customs or trade regulations"]'::jsonb, 'It allows customs authorities and consumers to verify where a garment was manufactured, supporting trade regulation, tariff classification, and consumer information rights', 'Country of origin labeling supports customs enforcement (correct tariff classification, trade agreement compliance) and gives consumers information about where their garment was made — a legal requirement enforced in many major import markets.', 2, '{"country-of-origin-label"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is ''sizing chart'' (size chart) standardization intended to help address in the apparel industry?', '["Reducing confusion/inconsistency from different brands using different actual measurements for the same nominal size label (e.g., ''Medium'')","Size charts have no practical purpose and are purely decorative marketing material","Sizing charts are legally identical and standardized across all brands worldwide with zero variation","Size charts only apply to children''s clothing, never adult apparel"]'::jsonb, 'Reducing confusion/inconsistency from different brands using different actual measurements for the same nominal size label (e.g., ''Medium'')', 'Since different brands (and even different garment styles within the same brand) can use quite different actual measurements for the same size label, a clear size chart helps consumers understand the SPECIFIC measurements behind that brand/style''s sizing, reducing fit confusion and returns.', 2, '{"size-chart"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'What is a ''vanity sizing'' phenomenon sometimes discussed in the apparel/retail industry?', '["A trend where brands label garments with a smaller size number than the actual measurements would traditionally suggest, appealing to consumer size perception","A legally mandated sizing standard used across the entire industry with zero brand variation","A sizing system used exclusively for children''s clothing","A term describing size charts that are printed using decorative fonts"]'::jsonb, 'A trend where brands label garments with a smaller size number than the actual measurements would traditionally suggest, appealing to consumer size perception', 'Vanity sizing describes the informal trend where a brand''s labeled size (e.g., ''Size 8'') corresponds to actual body measurements that would have been labeled a larger size in earlier decades — often attributed to brands wanting to make consumers feel favorably about the size number on their garment.', 2, '{"vanity-sizing"}'::text[]);
